# Let me try one more strategy: "closest non-8 neighbor" fill
# Find the nearest non-8 cell (in Manhattan distance) and copy its value

from collections import deque

def closest_neighbor_fill(grid):
    result = [[grid[r][c] for c in range(30)] for r in range(30)]

    # For each 8, find closest non-8 by BFS
    for r in range(30):
        for c in range(30):
            if grid[r][c] == 8:
                # BFS to find nearest non-8
                queue = deque()
                visited = {(r, c)}
                for nr, nc in [(r+1,c), (r-1,c), (r,c+1), (r,c-1)]:
                    if 0 <= nr < 30 and 0 <= nc < 30 and grid[nr][nc] != 8:
                        queue.append((nr, nc, 1))
                        visited.add((nr, nc))

                found = None
                while queue:
                    nr, nc, dist = queue.popleft()
                    if found is None:
                        found = (nr, nc, dist)
                    if found and dist > dist:
                        break
                    for nnr, nnc in [(nr+1,nc), (nr-1,nc), (nr,nc+1), (nr,nc-1)]:
                        if 0 <= nnr < 30 and 0 <= nnc < 30 and (nnr, nnc) not in visited:
                            if grid[nnr][nnc] != 8:
                                visited.add((nnr, nnc))
                                queue.append((nnr, nnc, dist+1))

                if found:
                    result[r][c] = grid[found[0]][found[1]]
                else:
                    result[r][c] = 1  # fallback

    return result

# Try another approach: 3x3 majority fill for each 8
def majority_3x3_fill(grid):
    result = [[grid[r][c] for c in range(30)] for r in range(30)]

    from collections import Counter
    for r in range(30):
        for c in range(30):
            if grid[r][c] == 8:
                # Get 3x3 window (handling boundaries)
                vals = []
                for dr in range(max(0, r-1), min(30, r+2)):
                    for dc in range(max(0, c-1), min(30, c+2)):
                        vals.append(grid[dr][dc])
                # Count excluding 8s
                non8_vals = [v for v in vals if v != 8]
                if non8_vals:
                    mode = Counter(non8_vals).most_common(1)[0][0]
                    result[r][c] = mode
                else:
                    result[r][c] = 1  # fallback

    return result

# Try final attempt with row-majority (fills 8s with majority value from same row)
def row_majority_fill(grid):
    from collections import Counter
    result = []
    for r in range(30):
        row = grid[r]
        new_row = []
        for c in range(30):
            if row[c] == 8:
                non8 = [v for v in row if v != 8]
                if non8:
                    mode = Counter(non8).most_common(1)[0][0]
                    new_row.append(mode)
                else:
                    new_row.append(1)
            else:
                new_row.append(row[c])
        result.append(new_row)
    return result

# My choice: submit closest neighbor fill as final attempt
closest = closest_neighbor_fill(grid)

